class BIT {
    vector<int> nums;
    vector<int> tree;
    int n;

public:
    BIT(vector<int>& nums) {
        n = nums.size() + 1;
        this->nums.resize(n);
        tree.resize(n, 0);
        for (int i = 0; i < nums.size(); i++) {
            update(i, nums[i]);
        }
    }

    void update(int index, int val) {
        index++;
        int diff = val - nums[index];
        nums[index] = val;
        while (index < n) {
            tree[index] += diff;
            index += index & -index;
        }
    }

    int prefixSum(int index) {
        int totalSum = 0;
        while (index > 0) {
            totalSum += tree[index];
            index -= index & -index;
        }
        return totalSum;
    }

    int query(int left, int right) {
        return prefixSum(right + 1) - prefixSum(left);
    }
};

class NumArray {
    BIT bit;

public:
    NumArray(vector<int>& nums) : bit(nums) {}

    void update(int index, int val) {
        bit.update(index, val);
    }

    int sumRange(int left, int right) {
        return bit.query(left, right);
    }
};
